import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Card, CardContent, CircularProgress, Alert,
  Avatar, Chip, Badge, Divider
} from '@mui/material';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import PersonIcon from '@mui/icons-material/Person';
import BusinessIcon from '@mui/icons-material/Business';

const orgColors = [
  { bg: 'rgba(99,102,241,0.08)', border: '#6366f1', badge: '#6366f1' },
  { bg: 'rgba(236,72,153,0.08)', border: '#ec4899', badge: '#ec4899' },
  { bg: 'rgba(16,185,129,0.08)', border: '#10b981', badge: '#10b981' },
  { bg: 'rgba(245,158,11,0.08)', border: '#f59e0b', badge: '#f59e0b' },
  { bg: 'rgba(59,130,246,0.08)', border: '#3b82f6', badge: '#3b82f6' },
];

const TreeNode = ({ node, depth = 0 }) => {
  const color = orgColors[depth % orgColors.length];
  const hasChildren = node.children && node.children.length > 0;
  const hasEmployees = node.employees && node.employees.length > 0;

  return (
    <Box sx={{ ml: depth > 0 ? 4 : 0, position: 'relative' }}>
      {/* Connector line from parent */}
      {depth > 0 && (
        <Box sx={{
          position: 'absolute', left: -24, top: 0, bottom: 0, width: 2,
          bgcolor: 'divider',
        }} />
      )}

      {/* Node Card */}
      <Card variant="outlined" sx={{
        mb: 1.5, position: 'relative',
        borderLeft: `4px solid ${color.border}`,
        background: color.bg,
        backdropFilter: 'blur(12px)',
        transition: 'all 0.2s ease',
        '&:hover': { transform: 'translateX(-4px)', boxShadow: `0 4px 16px ${color.border}20` },
      }}>
        <CardContent sx={{ py: 1.5, display: 'flex', alignItems: 'center', gap: 1.5, flexWrap: 'wrap' }}>
          <Avatar sx={{
            width: 36, height: 36, fontSize: 14, fontWeight: 700,
            background: `linear-gradient(135deg, ${color.border}, ${color.border}88)`,
          }}>
            <AccountTreeIcon sx={{ fontSize: 18 }} />
          </Avatar>
          <Box sx={{ flex: 1, minWidth: 120 }}>
            <Typography variant="body2" fontWeight={700}>{node.title}</Typography>
            <Typography variant="caption" color="textSecondary">
              {node.department_name || ''} — سطح {node.level}
            </Typography>
          </Box>
          {hasEmployees && (
            <Chip
              icon={<PersonIcon sx={{ fontSize: 14 }} />}
              label={`${node.employees.length} پرسنل`}
              size="small"
              sx={{ bgcolor: `${color.badge}18`, color: color.badge, fontWeight: 600 }}
            />
          )}
        </CardContent>

        {/* Employees list */}
        {hasEmployees && (
          <Box sx={{ px: 2, pb: 1.5, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
            {node.employees.map(emp => (
              <Chip
                key={emp.id}
                avatar={<Avatar sx={{ bgcolor: color.badge }}>{emp.full_name?.charAt(0)}</Avatar>}
                label={`${emp.full_name} (${emp.employee_id})`}
                size="small"
                variant="outlined"
              />
            ))}
          </Box>
        )}
      </Card>

      {/* Children */}
      {hasChildren && (
        <Box>
          {node.children.map(child => (
            <TreeNode key={child.id} node={child} depth={depth + 1} />
          ))}
        </Box>
      )}
    </Box>
  );
};

const OrgChartPage = () => {
  const { t } = useTranslation();
  const { data, isLoading, error } = useQuery({
    queryKey: ['orgchart-tree'],
    queryFn: () => axiosInstance.get('/org-chart/positions/tree/').then(r => r.data),
  });

  return (
    <Box>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 3 }}>
        <Avatar sx={{
          width: 48, height: 48,
          background: 'linear-gradient(135deg, #6366f1, #ec4899)',
          boxShadow: '0 4px 16px rgba(99,102,241,0.3)',
        }}>
          <AccountTreeIcon sx={{ fontSize: 28, color: '#fff' }} />
        </Avatar>
        <Box>
          <Typography variant="h4" fontWeight={800}>{t('orgchart.title')}</Typography>
          <Typography variant="body2" color="textSecondary">ساختار سازمانی شرکت</Typography>
        </Box>
      </Box>

      <Paper sx={{ p: 3 }}>
        {isLoading ? (
          <Box sx={{ textAlign: 'center', p: 6 }}><CircularProgress /></Box>
        ) : error ? (
          <Alert severity="error">
            خطا در دریافت چارت سازمانی. مطمئن شوید داده‌های نمونه بارگذاری شده است:
            <Box component="pre" sx={{ mt: 1, p: 1, bgcolor: 'rgba(0,0,0,0.04)', borderRadius: 1, fontSize: 12 }}>
              cd C:\HRMS\hrms_project{'\n'}python manage.py setup_dev{'\n'}python manage.py runserver
            </Box>
          </Alert>
        ) : !data || data.length === 0 ? (
          <Box sx={{ textAlign: 'center', p: 6 }}>
            <AccountTreeIcon sx={{ fontSize: 56, color: 'text.disabled', mb: 2 }} />
            <Typography variant="h6" color="textSecondary" gutterBottom>چارت سازمانی خالی است</Typography>
            <Typography variant="body2" color="textDisabled" sx={{ mb: 2 }}>
              برای ایجاد چارت سازمانی، دستور زیر را اجرا کنید:
            </Typography>
            <Paper variant="outlined" sx={{ p: 1.5, display: 'inline-block', textAlign: 'left', bgcolor: 'rgba(0,0,0,0.02)' }}>
              <code style={{ fontSize: 13 }}>
                cd C:\HRMS\hrms_project<br />
                python manage.py setup_dev
              </code>
            </Paper>
          </Box>
        ) : (
          <Box>
            {data.map(node => (
              <TreeNode key={node.id} node={node} depth={0} />
            ))}
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default OrgChartPage;
